from scipy.optimize import root_scalar
import numpy as np

def Q(z):
    return z**4 - 6*z**2 + 4*z - 3

def Q_prime(z):
    return z**3 - 3*z + 1

# Find roots of Q'(z) = 0 (z^3 - 3z + 1 = 0)
roots_of_Q_prime = []
# Test boundaries near the known roots
try:
    root = root_scalar(Q_prime, bracket=[-2, -1])
    roots_of_Q_prime.append(root.root)
except ValueError:
    pass
try:
    root = root_scalar(Q_prime, bracket=[0, 1])
    roots_of_Q_prime.append(root.root)
except ValueError:
    pass
try:
    root = root_scalar(Q_prime, bracket=[1, 2])
    roots_of_Q_prime.append(root.root)
except ValueError:
    pass

print("Roots of Q'(z) (critical points):")
for r in roots_of_Q_prime:
    print(f"z = {r}")

# Check Q(z) values at these roots
print("\nQ(z) at critical points:")
for r in roots_of_Q_prime:
    print(f"Q({r}) = {Q(r)}")

